export const PROG_GROUPS: { id: ProgGroup; label: string; sub: string }[] = [
  { id: "target", label: "Target Areas", sub: "Train a specific body part." },
  { id: "style", label: "Styles", sub: "How you like to train." },
  { id: "goal", label: "Goal based", sub: "What you're working towards." },
];
export function headersInGroup(g: ProgGroup): ProgramHeader[] { return PROGRAM_HEADERS.filter((h) => h.group === g); }

export const PROG_LEVELS: { id: ProgLevel; label: string }[] = [
  { id: "beginner", label: "Beginner" },
  { id: "medium", label: "Medium" },
  { id: "advanced", label: "Advance" },
];
export const PROG_TARGETS: { id: ProgFocus; label: string }[] = [
  { id: "full-body", label: "Full body" },
  { id: "upper-body", label: "Upper body" },
  { id: "legs", label: "Lower body" },
  { id: "abs", label: "Core / Abs" },
  { id: "endurance", label: "Cardio" },
];
// equipment chips shown inside a Target Areas header
export const PROG_EQUIP: { id: ProgEquip; label: string }[] = [
  { id: "none", label: "No equipment" },
  { id: "dumbbells", label: "Dumbbells" },
  { id: "resistance-band", label: "Resistance band" },
  { id: "kettlebells", label: "Kettlebells" },
];
export function progEquipLabel(e: ProgEquip): string {
  return e === "dumbbells" ? "Dumbbells" : e === "resistance-band" ? "Resistance band" : e === "kettlebells" ? "Kettlebells" : e === "gym" ? "Gym" : "No equipment";
}

export interface ProgFilters { levels: ProgLevel[]; targets: ProgFocus[]; equips: ProgEquip[] }
export const EMPTY_PROG_FILTERS: ProgFilters = { levels: [], targets: [], equips: [] };

export function matchItem(it: ProgramItem, f: ProgFilters): boolean {
  if (f.levels.length && !f.levels.includes(it.level)) return false;
  if (f.targets.length && !f.targets.includes(it.focus)) return false;
  if (f.equips.length && !f.equips.includes(it.equip)) return false;
  return true;
}
export function progLevelLabel(l: ProgLevel): string {
  return l === "beginner" ? "Beginner" : l === "medium" ? "Medium" : "Advance";
}
export function progFocusLabel(f: ProgFocus): string {
  return (PROG_TARGETS.find((t) => t.id === f) || { label: f }).label;
}
export function getProgramItem(id: string): ProgramItem | undefined {
  for (const h of PROGRAM_HEADERS) for (const s of h.subs) { const it = s.items.find((x) => x.id === id); if (it) return it; }
  return undefined;
}
